"use client";

import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  CONFERENCE_NAMES,
  summarizeStandings,
} from "@/features/standings/standings-schema";
import { ScrollArea } from "@/components/ui/scroll-area";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import type {
  Conference,
  StandingsData,
  StandingsTeam,
} from "@/features/standings/standings-schema";

export type StandingsCardState = "streaming" | "loading" | "ready" | "error";

export interface StandingsCardProperties {
  readonly state: StandingsCardState;
  /**
  The conference from the props, shown before the data arrives.
  */
  readonly conference?: Conference;
  readonly data?: StandingsData;
  readonly error?: string;
  readonly className?: string;
}

/**
One plain surface for the whole card, wide enough for every column. The table scrolls sideways when the card is narrower.
*/
const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-[720px]`;

const MUTED = "text-muted-foreground";

const STAT = "text-center whitespace-nowrap tabular-nums";

/**
The stat columns after the team, left to right, as on a standings page.
*/
const COLUMNS = [
  { key: "wins", label: "W", title: "Wins" },
  { key: "losses", label: "L", title: "Losses" },
  { key: "winPercent", label: "Pct", title: "Win percentage" },
  { key: "gamesBehind", label: "GB", title: "Games behind" },
  { key: "conference", label: "Conf", title: "Conference record" },
  { key: "home", label: "Home", title: "Home record" },
  { key: "away", label: "Away", title: "Away record" },
  { key: "lastTen", label: "L10", title: "Last ten games" },
  { key: "streak", label: "Strk", title: "Streak" },
] as const satisfies readonly {
  key: keyof StandingsTeam;
  label: string;
  title: string;
}[];

const TEAMS_PER_CONFERENCE = 15;

/**
One of the logo's two images: the light one, or the one ESPN draws for dark backgrounds. The theme hides the other.
*/
const LogoImage = ({
  src,
  onError,
  className,
}: {
  readonly src: string;
  readonly onError: () => void;
  readonly className: string;
}) => (
  // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the logo host into the installer's next.config; onError swaps in the letters, it is not a user interaction
  <img
    src={src}
    alt=""
    width={24}
    height={24}
    loading="lazy"
    onError={onError}
    className={cn("size-6 object-contain", className)}
  />
);

const TeamLogo = ({ team }: { readonly team: StandingsTeam }) => {
  const [failed, setFailed] = useState(false);
  if (failed || !team.logo) {
    return (
      <span
        aria-hidden
        className="flex size-6 shrink-0 items-center justify-center text-[10px]"
      >
        {team.abbreviation}
      </span>
    );
  }
  return (
    <span aria-hidden className="flex size-6 shrink-0">
      <LogoImage
        src={team.logo}
        onError={() => setFailed(true)}
        className="dark:hidden"
      />
      <LogoImage
        src={team.logoDark ?? team.logo}
        onError={() => setFailed(true)}
        className="hidden dark:block"
      />
    </span>
  );
};

const Header = ({
  conference,
  season,
}: {
  readonly conference: Conference;
  readonly season?: string;
}) => (
  <header className="flex items-center justify-between gap-3 text-sm">
    <p className="min-w-0 truncate">
      <span className="text-blue-600 dark:text-blue-400">NBA</span>
      <span className={MUTED}> · {CONFERENCE_NAMES[conference]}</span>
    </p>
    {season ? (
      <p className={cn(MUTED, "shrink-0 tabular-nums")}>{season}</p>
    ) : null}
  </header>
);

/**
The table runs to the card's edges, so its rows line up with the header text, and scrolls sideways on a narrow screen.
*/
const StandingsTable = ({ data }: { readonly data: StandingsData }) => (
  <ScrollArea orientation="horizontal" className="-mx-1">
    <Table className="min-w-[560px] text-sm">
      <caption className="sr-only">
        {CONFERENCE_NAMES[data.conference]} standings, {data.season}
      </caption>
      <TableHeader>
        <TableRow>
          <TableHead scope="col">Team</TableHead>
          {COLUMNS.map((column) => (
            <TableHead key={column.key} scope="col" className={STAT}>
              <abbr title={column.title} className="no-underline">
                {column.label}
              </abbr>
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {data.teams.map((team, index) => (
          <TableRow key={team.abbreviation} index={index}>
            <TableCell>
              <span className="flex min-w-0 items-center gap-3">
                <span className="w-5 shrink-0 text-right tabular-nums">
                  {team.rank}
                </span>
                <TeamLogo team={team} />
                <span className="truncate whitespace-nowrap">
                  {team.shortName}
                </span>
              </span>
            </TableCell>
            {COLUMNS.map((column) => (
              <TableCell key={column.key} className={STAT}>
                {team[column.key]}
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  </ScrollArea>
);

const StandingsError = ({
  conference,
  message = "The standings service didn't respond. Try again in a moment.",
}: {
  readonly conference?: Conference;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {conference
        ? `Couldn't load the ${CONFERENCE_NAMES[conference]} standings`
        : "Couldn't load the standings"}
    </p>
    <p className={cn(MUTED, "text-xs")}>{message}</p>
  </div>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <div className={cn("bg-muted animate-pulse rounded", className)} />
);

const SKELETON_ROWS = Array.from(
  { length: TEAMS_PER_CONFERENCE },
  (_, index) => `row-${index + 1}`
);

/**
The card while its data is on the way: the same header and one row per team at the table's height, so nothing moves when the standings land.
*/
export const StandingsCardSkeleton = ({
  conference,
  className,
}: {
  readonly conference?: Conference;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "block", className)}>
    <span className="sr-only">
      {conference
        ? `Loading the ${CONFERENCE_NAMES[conference]} standings`
        : "Loading the standings"}
    </span>
    <div aria-hidden className="flex flex-col gap-3">
      {conference ? (
        <Header conference={conference} />
      ) : (
        <div className="flex h-5 items-center">
          <Bar className="h-3.5 w-44" />
        </div>
      )}
      <div className="flex flex-col">
        {/* The header row and each team row are 37px: 36 on the ladder plus a 1px rule. */}
        <div className="flex h-[37px] items-center px-3">
          <Bar className="h-3.5 w-12" />
        </div>
        {SKELETON_ROWS.map((row) => (
          <div key={row} className="flex h-[37px] items-center gap-3 px-3">
            <Bar className="size-6 rounded-full" />
            <Bar className="h-3.5 w-28" />
          </div>
        ))}
      </div>
    </div>
  </output>
);

export default function StandingsCard({
  state,
  conference,
  data,
  error,
  className,
}: StandingsCardProperties) {
  if (state === "ready" && data) {
    return (
      <section
        aria-label={summarizeStandings(data)}
        className={cn(CARD_FRAME, "flex flex-col gap-3", className)}
      >
        <Header conference={data.conference} season={data.season} />
        <StandingsTable data={data} />
      </section>
    );
  }
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <StandingsError conference={conference} message={error} />
      </div>
    );
  }
  return (
    <StandingsCardSkeleton conference={conference} className={className} />
  );
}

"use client";

import { useEffect, useState } from "react";
import StandingsCard from "@/features/standings/components/standings-card";
import { loadStandings } from "@/features/standings/standings-requests";
import {
  errorMessage,
  parseConference,
} from "@/features/standings/standings-schema";
import type { StandingsData } from "@/features/standings/standings-schema";

/**
What came back for one conference. A result for the other conference reads as still loading, so the card never flashes the wrong table.
*/
type Result =
  | { key: string; status: "ready"; data: StandingsData }
  | { key: string; status: "error"; message: string };

export default function LiveStandingsCard({
  conference: requested,
  streaming = false,
  className,
}: {
  /**
  "east" or "west"; anything else waits.
  */
  readonly conference?: string;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [result, setResult] = useState<Result | null>(null);
  const conference = requested ? parseConference(requested) : null;

  useEffect(() => {
    let isCancelled = false;
    const run = async () => {
      if (!conference) {
        return;
      }
      let next: Result;
      try {
        next = {
          data: await loadStandings(conference),
          key: conference,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: conference,
          message: errorMessage(error, "Standings lookup failed."),
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming) {
      run();
    }
    return () => {
      isCancelled = true;
    };
  }, [conference, streaming]);

  if (streaming || !conference) {
    return (
      <StandingsCard
        state="streaming"
        conference={conference ?? undefined}
        className={className}
      />
    );
  }
  const current = result?.key === conference ? result : null;
  if (current?.status === "ready") {
    return (
      <StandingsCard state="ready" data={current.data} className={className} />
    );
  }
  if (current?.status === "error") {
    return (
      <StandingsCard
        state="error"
        conference={conference}
        error={current.message}
        className={className}
      />
    );
  }
  return (
    <StandingsCard
      state="loading"
      conference={conference}
      className={className}
    />
  );
}

import { z } from "zod";
import { CONFERENCES } from "@/features/standings/standings-schema";

export const standingsCatalogEntry = {
  description:
    "The NBA standings for one conference this regular season: each team's place, wins, losses, win percentage, games behind, and its records against the conference, at home, away and over the last ten games, with its current streak. It fetches its own data. Use it whenever the user asks for the NBA standings, a conference's table, who leads the East or the West, or where a team stands. For both conferences, or the whole league, show two cards in a CardGroup, east first. For one team, show its conference.",
  props: z.object({
    conference: z
      .enum(CONFERENCES)
      .describe(
        'The conference: "east" for the Eastern Conference, "west" for the Western Conference.'
      ),
  }),
};

import { listOf } from "@/features/chat/lookup";
import { loadStandings } from "@/features/standings/standings-requests";
import {
  CONFERENCE_NAMES,
  parseConference,
} from "@/features/standings/standings-schema";
import type { CardLookup } from "@/features/chat/lookup";

function conferenceOf(properties: Record<string, unknown>) {
  return typeof properties.conference === "string"
    ? parseConference(properties.conference)
    : null;
}

export const standingsLookup: CardLookup = {
  intent: (conferences) => `The ${listOf(conferences)} standings`,
  load: async (properties) => {
    const conference = conferenceOf(properties);
    if (!conference) {
      throw new Error("Pick a conference: east or west.");
    }
    return await loadStandings(conference);
  },
  sources: () => [
    {
      href: "https://www.espn.com/nba/standings",
      label: "espn.com/nba/standings",
    },
  ],
  subject: (properties) => {
    const conference = conferenceOf(properties);
    return conference ? CONFERENCE_NAMES[conference] : null;
  },
};

import type {
  Conference,
  StandingsData,
} from "@/features/standings/standings-schema";

const sharedStandingsRequests = new Map<
  Conference,
  { expiresAt: number; standings: Promise<StandingsData> }
>();
/**
Standings move once a game ends, so a minute is fresh enough.
*/
const REUSE_MS = 60_000;

async function fetchStandings(conference: Conference) {
  const response = await fetch(`/api/standings?conference=${conference}`);
  const body = (await response.json()) as StandingsData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Standings request failed: ${response.status}`
    );
  }
  return body;
}

async function requestStandings(conference: Conference) {
  try {
    return await fetchStandings(conference);
  } catch (error) {
    sharedStandingsRequests.delete(conference);
    throw error;
  }
}

export function loadStandings(conference: Conference) {
  const hit = sharedStandingsRequests.get(conference);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.standings;
  }
  const standings = requestStandings(conference);
  sharedStandingsRequests.set(conference, {
    expiresAt: Date.now() + REUSE_MS,
    standings,
  });
  return standings;
}

export function primeStandings(conference: Conference, data: StandingsData) {
  sharedStandingsRequests.set(conference, {
    expiresAt: Infinity,
    standings: Promise.resolve(data),
  });
}

import "server-only";
import type {
  Conference,
  StandingsData,
  StandingsTeam,
} from "@/features/standings/standings-schema";

// Server only: ESPN's site API doesn't allow browser requests (CORS).

/**
seasontype=2 is the regular season. Without it, ESPN answers with the preseason's standings while exhibition games are on. With no season, ESPN picks the current one.
*/
const STANDINGS =
  "https://site.api.espn.com/apis/v2/sports/basketball/nba/standings?seasontype=2";

const TIMEOUT_MS = 8000;

interface EspnStat {
  type: string;
  displayValue: string;
}

interface EspnEntry {
  team: {
    displayName: string;
    shortDisplayName: string;
    abbreviation: string;
    logos?: { href: string; rel: string[] }[];
  };
  stats: EspnStat[];
}

interface EspnStandings {
  children?: {
    abbreviation: string;
    standings: { seasonDisplayName?: string; entries: EspnEntry[] };
  }[];
}

const ESPN_CONFERENCE: Record<Conference, string> = {
  east: "East",
  west: "West",
};

const NO_GAMES = "0-0";
const NO_VALUE = "-";

function rowOf(entry: EspnEntry): Omit<StandingsTeam, "rank"> & {
  seed: number;
} {
  const stat = (type: string) =>
    entry.stats.find((item) => item.type === type)?.displayValue;
  const logos = entry.team.logos ?? [];
  const wins = Number(stat("wins") ?? 0);
  const losses = Number(stat("losses") ?? 0);
  return {
    abbreviation: entry.team.abbreviation,
    away: stat("road") ?? NO_GAMES,
    conference: stat("vsconf") ?? NO_GAMES,
    gamesBehind: stat("gamesbehind") ?? NO_VALUE,
    home: stat("home") ?? NO_GAMES,
    // ESPN leaves out the last ten until a team has played.
    lastTen: stat("lasttengames") ?? NO_GAMES,
    logo: logos.find((logo) => !logo.rel.includes("dark"))?.href ?? null,
    logoDark: logos.find((logo) => logo.rel.includes("dark"))?.href ?? null,
    losses,
    name: entry.team.displayName,
    seed: Number(stat("playoffseed") ?? 0),
    shortName: entry.team.shortDisplayName,
    streak: stat("streak") ?? NO_VALUE,
    winPercent: stat("winpercent") ?? ".000",
    wins,
  };
}

/**
A seed of 0 means none yet: those teams go after every seeded one.
*/
function placeOf(seed: number) {
  return seed || Number.MAX_SAFE_INTEGER;
}

/**
One conference's regular-season standings, first place first. ESPN sends the teams in no order, with each one's seed; before the season every seed is 0, and the teams keep ESPN's order.
*/
export async function getStandings(
  conference: Conference
): Promise<StandingsData> {
  const response = await fetch(STANDINGS, {
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`The standings service returned ${response.status}.`);
  }
  const body = (await response.json()) as EspnStandings;
  const group = body.children?.find(
    (child) => child.abbreviation === ESPN_CONFERENCE[conference]
  );
  if (!group) {
    throw new Error("The standings service sent no table for that conference.");
  }
  const teams = group.standings.entries
    .map(rowOf)
    .toSorted((first, second) => placeOf(first.seed) - placeOf(second.seed))
    .map((row, index) => {
      const { seed, ...team } = row;
      return { ...team, rank: seed || index + 1 };
    });
  return {
    asOf: Date.now(),
    conference,
    season: group.standings.seasonDisplayName ?? "",
    teams,
  };
}

/**
The NBA's two conferences.
*/
export const CONFERENCES = ["east", "west"] as const;

export type Conference = (typeof CONFERENCES)[number];

export const CONFERENCE_NAMES: Record<Conference, string> = {
  east: "Eastern Conference",
  west: "Western Conference",
};

/**
One team's row in the table.
*/
export interface StandingsTeam {
  /**
  Its place in the conference, 1 first.
  */
  rank: number;
  /**
  e.g. "Los Angeles Lakers".
  */
  name: string;
  /**
  e.g. "Lakers".
  */
  shortName: string;
  /**
  e.g. "LAL".
  */
  abbreviation: string;
  /**
  The team's logo, a square PNG. Null when ESPN has none for it.
  */
  logo: string | null;
  /**
  The same logo drawn for a dark background. Null when ESPN has none.
  */
  logoDark: string | null;
  wins: number;
  losses: number;
  /**
  As a scoreboard writes it: ".646".
  */
  winPercent: string;
  /**
  Games behind the conference leader: "11", "2.5", or "-" for the leader.
  */
  gamesBehind: string;
  /**
  Records as "W-L": against the conference, at home, away, and over the last ten games.
  */
  conference: string;
  home: string;
  away: string;
  lastTen: string;
  /**
  e.g. "W3", "L1", or "-" before the first game.
  */
  streak: string;
}

/**
One conference's standings.
*/
export interface StandingsData {
  conference: Conference;
  /**
  e.g. "2026-27".
  */
  season: string;
  teams: StandingsTeam[];
  /**
  Unix time in milliseconds the standings were read.
  */
  asOf: number;
}

/**
"west", "West", "Western Conference" and "western" all read "west". Null when it names neither conference.
*/
export function parseConference(value: string): Conference | null {
  const text = value.trim().toLowerCase();
  return CONFERENCES.find((conference) => text.startsWith(conference)) ?? null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeStandings(data: StandingsData): string {
  const name = CONFERENCE_NAMES[data.conference];
  const [leader] = data.teams;
  const lead = leader
    ? `: the ${leader.name} lead at ${leader.wins}-${leader.losses}`
    : "";
  return `${name} standings, ${data.season}${lead}.`;
}

import { getStandings } from "@/features/standings/standings-queries";
import {
  errorMessage,
  parseConference,
} from "@/features/standings/standings-schema";

const CACHE = "public, s-maxage=60, stale-while-revalidate=300";

const UPSTREAM_FAILED = 502;

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const conference = parseConference(searchParams.get("conference") ?? "");
  if (!conference) {
    return Response.json(
      { error: 'Pass a conference: "east" or "west".' },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getStandings(conference), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    return Response.json(
      { error: errorMessage(error, "Standings lookup failed.") },
      { status: UPSTREAM_FAILED }
    );
  }
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;
